DROP SCHEMA IF EXISTS biblioteca CASCADE;
CREATE SCHEMA biblioteca;
SET search_path TO biblioteca;

CREATE TABLE rol (
  "PK_id_rol"  INT GENERATED BY DEFAULT AS IDENTITY,
  "nombre_rol" varchar(50) NOT NULL,
  CONSTRAINT pk_rol PRIMARY KEY ("PK_id_rol"),
  CONSTRAINT uq_rol_nombre UNIQUE ("nombre_rol")
);

CREATE TABLE usuario (
  "PK_id_usuario" INT GENERATED BY DEFAULT AS IDENTITY,
  "FK_id_rol"     int          NOT NULL,
  "correo"        varchar(150) NOT NULL,
  "estado"        varchar(50)  NOT NULL DEFAULT 'activo',
  "contrasena"    varchar(255) NOT NULL,
  "nombres"       varchar(100) NOT NULL,
  "documento"     varchar(30)  NOT NULL,
  "apellidos"     varchar(100) NOT NULL,
  "telefono"      varchar(20),
  CONSTRAINT pk_usuario PRIMARY KEY ("PK_id_usuario"),
  CONSTRAINT uq_usuario_correo UNIQUE ("correo"),
  CONSTRAINT uq_usuario_documento UNIQUE ("documento"),
  CONSTRAINT ck_usuario_correo CHECK ("correo" LIKE '%_@_%.__%'),
  CONSTRAINT ck_usuario_estado CHECK ("estado" IN ('activo', 'inactivo', 'suspendido'))
);

CREATE TABLE libro (
  "PK_id_libro"            INT GENERATED BY DEFAULT AS IDENTITY,
  "titulo"                 varchar(200) NOT NULL,
  "autor"                  varchar(150) NOT NULL,
  "editorial"              varchar(100),
  "ejemplares_disponibles" int          NOT NULL DEFAULT 0,
  "anio_publicacion"       int,
  "categoria"              varchar(100),
  "isbn"                   varchar(20)  NOT NULL,
  CONSTRAINT pk_libro PRIMARY KEY ("PK_id_libro"),
  CONSTRAINT uq_libro_isbn UNIQUE ("isbn"),
  CONSTRAINT ck_libro_ejemplares CHECK ("ejemplares_disponibles" >= 0),
  CONSTRAINT ck_libro_anio CHECK ("anio_publicacion" BETWEEN 1400 AND 2100)
);

CREATE TABLE ejemplares (
  "PK_id_ejemplar" INT GENERATED BY DEFAULT AS IDENTITY,
  "FK_id_libro"    int         NOT NULL,
  "estado"         varchar(50) NOT NULL DEFAULT 'disponible',
  CONSTRAINT pk_ejemplares PRIMARY KEY ("PK_id_ejemplar"),
  CONSTRAINT ck_ejemplares_estado
    CHECK ("estado" IN ('disponible', 'prestado', 'danado', 'mantenimiento'))
);

CREATE TABLE prestamo (
  "PK_id_prestamo"    INT GENERATED BY DEFAULT AS IDENTITY,
  "FK_id_usuario"     int         NOT NULL,
  "FK_id_libro"       int         NOT NULL,
  "fecha_prestamo"    date        NOT NULL DEFAULT CURRENT_DATE,
  "estado_prestamo"   varchar(50) NOT NULL DEFAULT 'activo',
  "fecha_vencimiento" date        NOT NULL,
  CONSTRAINT pk_prestamo PRIMARY KEY ("PK_id_prestamo"),
  CONSTRAINT ck_prestamo_estado CHECK ("estado_prestamo" IN ('activo', 'devuelto', 'vencido')),
  CONSTRAINT ck_prestamo_fechas CHECK ("fecha_vencimiento" >= "fecha_prestamo")
);

CREATE TABLE devolucion (
  "FK_id_prestamo"    int         NOT NULL,
  "FK_id_ejemplar"    int         NOT NULL,
  "estado_devolucion" varchar(50) NOT NULL,
  "fecha_devolucion"  date        NOT NULL DEFAULT CURRENT_DATE,
  CONSTRAINT pk_devolucion PRIMARY KEY ("FK_id_prestamo", "FK_id_ejemplar"),
  CONSTRAINT ck_devolucion_estado CHECK ("estado_devolucion" IN ('a_tiempo', 'tardia', 'danado'))
); -- tabla débil que depende de préstamo; su PK combina el préstamo y el ejemplar.

INSERT INTO rol ("nombre_rol") VALUES ('lector');

-- ---------- Llaves foráneas ----------
ALTER TABLE usuario ADD CONSTRAINT fk_usuario_rol
  FOREIGN KEY ("FK_id_rol") REFERENCES rol ("PK_id_rol")
  ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE prestamo ADD CONSTRAINT fk_prestamo_usuario
  FOREIGN KEY ("FK_id_usuario") REFERENCES usuario ("PK_id_usuario")
  ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE prestamo ADD CONSTRAINT fk_prestamo_libro
  FOREIGN KEY ("FK_id_libro") REFERENCES libro ("PK_id_libro")
  ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE ejemplares ADD CONSTRAINT fk_ejemplares_libro
  FOREIGN KEY ("FK_id_libro") REFERENCES libro ("PK_id_libro")
  ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE devolucion ADD CONSTRAINT fk_devolucion_prestamo
  FOREIGN KEY ("FK_id_prestamo") REFERENCES prestamo ("PK_id_prestamo")
  ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE devolucion ADD CONSTRAINT fk_devolucion_ejemplar
  FOREIGN KEY ("FK_id_ejemplar") REFERENCES ejemplares ("PK_id_ejemplar")
  ON UPDATE CASCADE ON DELETE RESTRICT;